Here's a self-contained checkout page component. It includes the cart list, a validated delivery-address form, a Pay button with a loading state, and a "Back to cart" action — all typed with TypeScript and styled with plain CSS.

```tsx
// CheckoutPage.tsx
import React, { useMemo, useState } from "react";
import "./CheckoutPage.css";

export interface CartItem {
  id: string;
  name: string;
  price: number; // unit price in dollars
  quantity: number;
  imageUrl?: string;
}

export interface DeliveryAddress {
  fullName: string;
  street: string;
  city: string;
  postalCode: string;
  country: string;
  phone: string;
}

export interface CheckoutPageProps {
  cartItems: CartItem[];
  shippingCost?: number;
  taxRate?: number; // e.g. 0.08 for 8%
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress, total: number) => Promise<void> | void;
}

type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  street: "",
  city: "",
  postalCode: "",
  country: "",
  phone: "",
};

function formatCurrency(amount: number): string {
  return amount.toLocaleString(undefined, {
    style: "currency",
    currency: "USD",
  });
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) errors.fullName = "Full name is required.";
  if (!address.street.trim()) errors.street = "Street address is required.";
  if (!address.city.trim()) errors.city = "City is required.";
  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required.";
  } else if (!/^[A-Za-z0-9\- ]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = "Enter a valid postal code.";
  }
  if (!address.country.trim()) errors.country = "Country is required.";
  if (!address.phone.trim()) {
    errors.phone = "Phone number is required.";
  } else if (!/^[0-9+()\- ]{7,20}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number.";
  }

  return errors;
}

export default function CheckoutPage({
  cartItems,
  shippingCost = 5.99,
  taxRate = 0.08,
  onBackToCart,
  onPay,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [isPaying, setIsPaying] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [cartItems]
  );
  const tax = useMemo(() => subtotal * taxRate, [subtotal, taxRate]);
  const effectiveShipping = cartItems.length === 0 ? 0 : shippingCost;
  const total = subtotal + tax + effectiveShipping;

  const handleFieldChange =
    (field: keyof DeliveryAddress) =>
    (e: React.ChangeEvent<HTMLInputElement>) => {
      setAddress((prev) => ({ ...prev, [field]: e.target.value }));
      setErrors((prev) => ({ ...prev, [field]: undefined }));
    };

  const handlePay = async (e: React.FormEvent) => {
    e.preventDefault();
    setPayError(null);

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) return;
    if (cartItems.length === 0) {
      setPayError("Your cart is empty.");
      return;
    }

    setIsPaying(true);
    try {
      await onPay(address, total);
    } catch (err) {
      setPayError(
        err instanceof Error ? err.message : "Payment failed. Please try again."
      );
    } finally {
      setIsPaying(false);
    }
  };

  return (
    <div className="checkout-page">
      <button
        type="button"
        className="checkout-back-link"
        onClick={onBackToCart}
        disabled={isPaying}
      >
        &larr; Back to cart
      </button>

      <h1 className="checkout-title">Checkout</h1>

      <div className="checkout-layout">
        <section className="checkout-section" aria-labelledby="order-summary-heading">
          <h2 id="order-summary-heading" className="checkout-section-title">
            Order Summary
          </h2>

          {cartItems.length === 0 ? (
            <p className="checkout-empty">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {cartItems.map((item) => (
                <li key={item.id} className="cart-item">
                  <img
                    className="cart-item-image"
                    src={item.imageUrl ?? "/placeholder-product.png"}
                    alt={item.name}
                  />
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatCurrency(item.price * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <dl className="checkout-totals">
            <div className="checkout-totals-row">
              <dt>Subtotal</dt>
              <dd>{formatCurrency(subtotal)}</dd>
            </div>
            <div className="checkout-totals-row">
              <dt>Shipping</dt>
              <dd>{formatCurrency(effectiveShipping)}</dd>
            </div>
            <div className="checkout-totals-row">
              <dt>Tax</dt>
              <dd>{formatCurrency(tax)}</dd>
            </div>
            <div className="checkout-totals-row checkout-totals-row--total">
              <dt>Total</dt>
              <dd>{formatCurrency(total)}</dd>
            </div>
          </dl>
        </section>

        <section className="checkout-section" aria-labelledby="address-heading">
          <h2 id="address-heading" className="checkout-section-title">
            Delivery Address
          </h2>

          <form className="address-form" onSubmit={handlePay} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={handleFieldChange("fullName")}
                aria-invalid={Boolean(errors.fullName)}
                disabled={isPaying}
              />
              {errors.fullName && (
                <span className="field-error">{errors.fullName}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                value={address.street}
                onChange={handleFieldChange("street")}
                aria-invalid={Boolean(errors.street)}
                disabled={isPaying}
              />
              {errors.street && <span className="field-error">{errors.street}</span>}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={handleFieldChange("city")}
                  aria-invalid={Boolean(errors.city)}
                  disabled={isPaying}
                />
                {errors.city && <span className="field-error">{errors.city}</span>}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={handleFieldChange("postalCode")}
                  aria-invalid={Boolean(errors.postalCode)}
                  disabled={isPaying}
                />
                {errors.postalCode && (
                  <span className="field-error">{errors.postalCode}</span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                value={address.country}
                onChange={handleFieldChange("country")}
                aria-invalid={Boolean(errors.country)}
                disabled={isPaying}
              />
              {errors.country && (
                <span className="field-error">{errors.country}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={handleFieldChange("phone")}
                aria-invalid={Boolean(errors.phone)}
                disabled={isPaying}
              />
              {errors.phone && <span className="field-error">{errors.phone}</span>}
            </div>

            {payError && <p className="checkout-pay-error">{payError}</p>}

            <button
              type="submit"
              className="pay-button"
              disabled={isPaying || cartItems.length === 0}
            >
              {isPaying ? "Processing…" : `Pay ${formatCurrency(total)}`}
            </button>
          </form>
        </section>
      </div>
    </div>
  );
}
```

